// Native MathML generated by KaTeX keeps each HTML lesson self-contained without a separate font bundle.
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';

const require = createRequire(import.meta.url);
let markup;

export function inlineLessonMath() {
  if (!markup) {
    const bundle = require.resolve('katex/dist/katex.min.js');
    const license = readFileSync(join(dirname(bundle), '..', 'LICENSE'), 'utf8');
    const safeScript = file => readFileSync(file, 'utf8').replace(/<\/script/gi, '<\\/script')
      .replace(/^\/\/# sourceMappingURL=.*$/gm, '');
    const renderer = safeScript(new URL('../../harness/lesson-math.js', import.meta.url));
    markup = [
      '<style>',
      '.lesson-math { display: inline-block; max-width: 100%; overflow-x: auto; vertical-align: middle; }',
      '.lesson-math math { white-space: nowrap; math-style: normal; }',
      '.lesson-math annotation { display: none; }',
      '</style>',
      '<script>/*! KaTeX license\n' + license + '\n*/\n' + safeScript(bundle) + '</script>',
      '<script>' + renderer + '</script>'
    ].join('\n');
  }
  return markup;
}
